#include <stdio.h>
#include <string.h>

int main(int argc, char *argv[]) {
    // Too many arguments (including program name)
    if (argc > 65) {
        puts("TOO_MANY");
        return 0;
    }
    // No strings provided (only program name)
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    // Verify each argument length does not exceed 1024 characters
    for (int i = 1; i < argc; ++i) {
        if (strlen(argv[i]) > 1024) {
            puts("TOO_LONG");
            return 0;
        }
    }
    // Compute longest common prefix among all arguments (excluding program name)
    const char *first = argv[1];
    size_t prefix_len = strlen(first);
    // Limit to the shortest string length
    for (int i = 2; i < argc; ++i) {
        size_t len = strlen(argv[i]);
        if (len < prefix_len) {
            prefix_len = len;
        }
    }
    size_t i = 0;
    for (; i < prefix_len; ++i) {
        char c = first[i];
        for (int j = 2; j < argc; ++j) {
            if (argv[j][i] != c) {
                goto output;
            }
        }
    }
output:
    // Print the common prefix (may be empty) followed by a newline
    fwrite(first, 1, i, stdout);
    putchar('\n');
    return 0;
}
